import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const y=JSON.parse('{"title":"Qingyan / Z.ai glossary","description":"No procedures. Why Qingyan, Z.ai, ChatGLM, and Coding Plan are not the same thing.","frontmatter":{"title":"Qingyan / Z.ai glossary","description":"No procedures. Why Qingyan, Z.ai, ChatGLM, and Coding Plan are not the same thing.","domain":"product","tags":["coding-agent"],"role":"glossary"},"headers":[],"relativePath":"products/zhipu-chat/zhipu-chat-glossary.md","filePath":"products/zhipu-chat/zhipu-chat-glossary.md","lastUpdated":1787107158000}'),r={name:"products/zhipu-chat/zhipu-chat-glossary.md"};function i(s,t,d,l,h,g){return o(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="qingyan-z-ai-glossary" tabindex="-1">Qingyan / Z.ai glossary <a class="header-anchor" href="#qingyan-z-ai-glossary" aria-label="Permalink to &quot;Qingyan / Z.ai glossary&quot;">​</a></h1><p>No procedures. Why the names collide. Pick a door on the <a href="./">learning map</a>.</p><h2 id="things-that-say-zhipu-glm-z-ai" tabindex="-1">Things that say Zhipu / GLM / Z.ai <a class="header-anchor" href="#things-that-say-zhipu-glm-z-ai" aria-label="Permalink to &quot;Things that say Zhipu / GLM / Z.ai&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>What it is</th><th>What it is not</th></tr></thead><tbody><tr><td><strong>Qingyan</strong></td><td>China consumer assistant. Agreement: a generative AI product operated by Beijing Zhipu Huazhang Technology Co., Ltd. (<a href="https://chatglm.cn/pay/policy/vipservice" target="_blank" rel="noreferrer">paid agreement §1.1</a>). Door: <a href="https://chatglm.cn" target="_blank" rel="noreferrer">chatglm.cn</a></td><td>Not Coding Plan, not the API console</td></tr><tr><td><strong>Z.ai chat</strong></td><td>International consumer assistant. <a href="https://chat.z.ai" target="_blank" rel="noreferrer">chat.z.ai</a> title: Advanced AI Chatbot &amp; Agent</td><td>Not the SDK tutorial on <code>docs.z.ai</code></td></tr><tr><td><strong>Z.ai (company usage)</strong></td><td><a href="https://www.zhipuai.cn/zh" target="_blank" rel="noreferrer">zhipuai.cn</a> uses Z.ai as both brand and one first-party product</td><td>Not &quot;every Zhipu product is Z.ai&quot;</td></tr><tr><td><strong>ChatGLM</strong></td><td>2023 conversational model / older store copy (<a href="https://z.ai/company" target="_blank" rel="noreferrer">z.ai/company</a> timeline; App Store)</td><td>Not the product URL you type today</td></tr><tr><td><strong>GLM</strong></td><td>Model family. Open-platform intro: General Language Model (<a href="https://docs.bigmodel.cn/cn/guide/start/introduction" target="_blank" rel="noreferrer">docs.bigmodel.cn</a>)</td><td>Not one app</td></tr><tr><td><strong>GLM-5.2</strong></td><td>Flagship name on Qingyan and Z.ai pages on 2026-08-19; the research post hangs it on both chat and Coding Plan</td><td>Not &quot;the chat picker has only this forever&quot;</td></tr><tr><td><strong>GLM Coding Plan</strong></td><td>Subscription for Claude Code and similar tools (<a href="https://z.ai/subscribe" target="_blank" rel="noreferrer">z.ai/subscribe</a>)</td><td>Not Qingyan web setup</td></tr><tr><td><strong>ZCode</strong></td><td>Official coding tool (<a href="https://www.zhipuai.cn/zh/research/161" target="_blank" rel="noreferrer">research/161</a>)</td><td>Not the Chat tab on chat.z.ai</td></tr><tr><td><strong>AutoGLM</strong></td><td>Agent / report assistant on the company page and <a href="https://autoglm.zhipuai.cn" target="_blank" rel="noreferrer">autoglm.zhipuai.cn</a></td><td>Not a nickname for one Qingyan mode — official pages list it as its own product</td></tr><tr><td><strong>AutoClaw</strong></td><td>First-party product on the company page; marketing copy is a local OpenClaw client</td><td>Not merely another spelling of AutoGLM — the company page lists both</td></tr><tr><td><strong>CodeGeeX</strong></td><td>Coding assistant in official news</td><td>Not Qingyan</td></tr><tr><td><strong>BigModel</strong></td><td>China open platform <a href="https://bigmodel.cn" target="_blank" rel="noreferrer">bigmodel.cn</a></td><td>Not the chat membership center</td></tr><tr><td><strong>Qingying</strong></td><td>Video-generation benefit named in the paid agreement</td><td>Not a separate handbook on this site</td></tr></tbody></table><h2 id="two-legal-entities" tabindex="-1">Two legal entities <a class="header-anchor" href="#two-legal-entities" aria-label="Permalink to &quot;Two legal entities&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Qingyan</th><th>Z.ai</th></tr></thead><tbody><tr><td>Product URL</td><td>chatglm.cn</td><td>chat.z.ai / z.ai</td></tr><tr><td>Operator in the legal text</td><td>Beijing Zhipu Huazhang Technology Co., Ltd.</td><td>JINGSHENG HENGXING TECHNOLOGY PTE.LTD (<a href="https://docs.z.ai/legal-agreement/terms-of-use" target="_blank" rel="noreferrer">Terms</a>)</td></tr><tr><td>Official &quot;same login&quot; claim</td><td>None</td><td>None</td></tr></tbody></table><p>So <strong>do not</strong> draw Qingyan membership, Z.ai login, Coding Plan, and an open-platform API key as one pool. The Qingyan agreement only says Qingyan membership and open-platform paid features are independent and can stack (§4.4). It does not say the international site shares that account.</p><h2 id="an-in-chat-agent-is-not-a-repo-agent" tabindex="-1">An in-chat Agent is not a repo agent <a class="header-anchor" href="#an-in-chat-agent-is-not-a-repo-agent" aria-label="Permalink to &quot;An in-chat Agent is not a repo agent&quot;">​</a></h2><p>Qingyan&#39;s homepage calls itself an Agent: understand the goal, call tools, turn answers into deliverables. Z.ai&#39;s description says build websites, write code, long-horizon tasks.</p><p>That is still a <strong>chat surface</strong>:</p><ul><li>No official &quot;run Qingyan as a repo CLI&quot; steps.</li><li>Official repo / IDE coding sits on <strong>GLM Coding Plan</strong> and <strong>ZCode</strong> (research post, &quot;Agent&quot; section).</li><li>A page or script in the thread does not become a git commit on your machine.</li></ul><p>Analog: Qingyan / Z.ai chat ≈ Claude.ai. Coding Plan / ZCode power other coding tools. They are <strong>not</strong> this directory&#39;s Claude Code tutorial.</p><h2 id="do-not-write-as-fact" tabindex="-1">Do not write as fact <a class="header-anchor" href="#do-not-write-as-fact" aria-label="Permalink to &quot;Do not write as fact&quot;">​</a></h2><ul><li>&quot;Qingyan and chat.z.ai share one account&quot;</li><li>&quot;Free tier is N turns per day&quot; (common on third-party sites; the agreement says trust the membership page)</li><li>Treating one day&#39;s App Store RMB IAP table as the national price list</li><li>Product name &quot;ChatGLM web install of Coding Plan&quot;</li><li>Treating the <code>docs.z.ai</code> API model table as the Qingyan dropdown</li></ul><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./">Learning map</a></li><li><a href="./zhipu-chat.html">Tutorial</a></li><li><a href="./zhipu-chat-cheatsheet.html">Cheatsheet</a></li></ul>',16)])])}const f=a(r,[["render",i]]);export{y as __pageData,f as default};
